Here is an example of how you can achieve this using QT5 in C++:

```cpp
#include <QApplication>
#include <QFileDialog>
#include <QDirIterator>
#include <QMessageBox>
#include <QAxBase>
#include <QAxObject>
#include <QTextStream>

int main(int argc, char *argv[])
{
    QApplication app(argc, argv);

    // Prompt the user to select a directory
    QString dirPath = QFileDialog::getExistingDirectory(nullptr, "Select a directory", QDir::homePath());
    if (dirPath.isEmpty()) {
        QMessageBox::critical(nullptr, "Error", "No directory selected. Exiting.");
        return 1;
    }

    // Create a new folder for csv files
    QString csvFolderPath = dirPath + "/CSV_Files";
    QDir().mkpath(csvFolderPath);

    // Iterate through files in the selected directory
    QDirIterator it(dirPath, QStringList() << "*.xls" << "*.xlsx", QDir::Files, QDirIterator::Subdirectories);
    while (it.hasNext()) {
        QString filePath = it.next();
        QAxObject excel("Excel.Application");
        if (!excel.isNull()) {
            QAxObject *workbooks = excel.querySubObject("Workbooks");
            workbooks->dynamicCall("Open(const QString&)", QDir::toNativeSeparators(filePath));
            QAxObject *workbook = excel.querySubObject("ActiveWorkBook");

            // Convert Excel files to CSV
            QString csvFilePath = csvFolderPath + "/" + QFileInfo(filePath).baseName() + ".csv";
            workbook->dynamicCall("SaveAs(const QString&, int)", QDir::toNativeSeparators(csvFilePath), 6); // 6 = CSV File Format
            workbook->dynamicCall("Close()");
            delete workbook;
            delete workbooks;
            excel.dynamicCall("Quit()");
        }
    }

    QMessageBox::information(nullptr, "Success", "Files converted to CSV successfully!");

    return 0;
}
```

This code uses the QFileDialog class to prompt the user to select a directory. It then iterates through all Excel files in that directory using QDirIterator and converts them to CSV format using QAxObject, which is a COM-based interface for accessing Microsoft Office applications. The converted CSV files are saved in a new folder within the selected directory.

Please note that you will need to link your project with the Qt5 libraries and include the necessary headers in your C++ code to run this program.

